//! Languages and themes supported by Favnyr.
//!
//! The UI string translation tables live on the `favnyr-gui` side (coupled
//! to the structs generated by Slint). Here we only define the enums
//! and their TOML serialization for persistence in `config.toml`.

use serde::{Deserialize, Serialize};

/// Interface language. The user can change it in Settings; persisted
/// in `config.toml` (`language = "fr"` etc.).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum Lang {
    #[default]
    En,
    Fr,
    Es,
    De,
    It,
    Ru,
    Zh,
    Ja,
}

impl Lang {
    /// Short ISO 639-1 identifier.
    pub fn code(self) -> &'static str {
        match self {
            Lang::En => "en",
            Lang::Fr => "fr",
            Lang::Es => "es",
            Lang::De => "de",
            Lang::It => "it",
            Lang::Ru => "ru",
            Lang::Zh => "zh",
            Lang::Ja => "ja",
        }
    }

    /// Name of the language in its own language (Settings selector).
    pub fn native_name(self) -> &'static str {
        match self {
            Lang::En => "English",
            Lang::Fr => "Français",
            Lang::Es => "Español",
            Lang::De => "Deutsch",
            Lang::It => "Italiano",
            Lang::Ru => "Русский",
            Lang::Zh => "简体中文",
            Lang::Ja => "日本語",
        }
    }

    /// All supported languages, in display order.
    pub fn all() -> &'static [Lang] {
        &[
            Lang::En,
            Lang::Fr,
            Lang::Es,
            Lang::De,
            Lang::It,
            Lang::Ru,
            Lang::Zh,
            Lang::Ja,
        ]
    }

    /// Parses an ISO code; falls back to `En` if unrecognized.
    pub fn from_code(code: &str) -> Lang {
        match code {
            "fr" => Lang::Fr,
            "es" => Lang::Es,
            "de" => Lang::De,
            "it" => Lang::It,
            "ru" => Lang::Ru,
            "zh" => Lang::Zh,
            "ja" => Lang::Ja,
            _ => Lang::En,
        }
    }
}

/// Interface theme preference. `Auto` follows the system theme.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, Default)]
#[serde(rename_all = "lowercase")]
pub enum Theme {
    #[default]
    Auto,
    Light,
    Dark,
}

impl Theme {
    pub fn code(self) -> &'static str {
        match self {
            Theme::Auto => "auto",
            Theme::Light => "light",
            Theme::Dark => "dark",
        }
    }

    pub fn all() -> &'static [Theme] {
        &[Theme::Auto, Theme::Light, Theme::Dark]
    }

    pub fn from_code(code: &str) -> Theme {
        match code {
            "light" => Theme::Light,
            "dark" => Theme::Dark,
            _ => Theme::Auto,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_is_english() {
        assert_eq!(Lang::default(), Lang::En);
    }

    #[test]
    fn lang_code_round_trip() {
        for lang in Lang::all() {
            assert_eq!(Lang::from_code(lang.code()), *lang);
        }
    }

    #[test]
    fn lang_unknown_falls_back_to_english() {
        // The codes are checked against `all()` rather than assumed unknown:
        // this test used "zh" as its example and broke the day Chinese was
        // added. A sample that names a real language proves nothing.
        let known: Vec<&str> = Lang::all().iter().map(|lang| lang.code()).collect();
        for code in ["", "xx", "qqq", "EN", "fr-CA", "zz"] {
            assert!(!known.contains(&code), "{code} is a supported language");
            assert_eq!(Lang::from_code(code), Lang::En, "{code}");
        }
    }

    #[test]
    fn theme_default_is_auto() {
        assert_eq!(Theme::default(), Theme::Auto);
    }

    #[test]
    fn theme_code_round_trip() {
        for t in Theme::all() {
            assert_eq!(Theme::from_code(t.code()), *t);
        }
    }
}
